 let wakeToken=null,wakePending=false,wakeRetry=0;
 function mobileWake(){if(!window.HAMobileBridge)return;const wanted=active()&&S.config.keepAwake&&document.visibilityState==='visible';if(!wanted){wakeToken?.release().catch(()=>{});wakeToken=null;return}if(!wakeToken&&!wakePending&&Date.now()>wakeRetry){wakeRetry=Date.now()+30000;if(!navigator.wakeLock){return}wakePending=true;navigator.wakeLock.request('screen').then(lock=>{if(!active()||!S.config.keepAwake||document.visibilityState!=='visible'){lock.release();return}wakeToken=lock;lock.addEventListener('release',()=>{if(wakeToken===lock)wakeToken=null})}).catch(()=>log('Trình duyệt chưa cấp giữ màn hình thức')).finally(()=>wakePending=false)}}
