     if(now-S.frameAt>frameMaxAge()){release();S.planner.suspend();status(document.hidden?'Tab game đang ẩn; dùng cửa sổ riêng còn hiển thị để tiếp tục nhận hình':'Chờ dữ liệu canvas mới')}
