     if(now-S.lastMove>=S.config.moveMs){move(HAF.step(S.config.pattern,S.steps++));S.lastMove=now}
     if(now-S.frameAt<750){const me=HAP.validate(S.frame)&&HAP.player(S.frame,selectedDex());if(me)useSkill(now,{me,phase:'explore'})}
     if(now-S.frameAt<750){const me=HAP.validate(S.frame)&&HAP.player(S.frame,selectedDex());if(me)useOrb(now,{me,phase:'explore'})}
